// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ContestClarification) predicate.ContestClarification {
	return predicate.ContestClarification(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ContestClarification) predicate.ContestClarification {
	return predicate.ContestClarification(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ContestClarification) predicate.ContestClarification {
	return predicate.ContestClarification(sql.NotPredicates(p))
}
